ids=['fixed-wing','vtol','cube-vtol','tiltrotor','talon-vtol','helicopter','heavy-lift','multirotor','fpv-10','inav-fpv','s500','drone-rover-docking','usv','rescue-usv','hybrid-wheeled-uav','vision']
