ids.insert(6,'delivery-drone');names.insert(6,'Heavy-lift delivery drone: 20 km mission');titles=dict(zip(ids,names));titles['heavy-lift']='DARPA Lift Challenge heavy-lift support';labels={'air':'UAV & UAS','land':'Ground robotics','sea':'USV & marine autonomy','avionics':'Avionics & perception'}
def visual(d,pre='',kind='cover'):
 if d.get('reference_images'):im=d['reference_images'][0];src=im['src'];cap=im['caption']
 elif d.get('photo_verified') and d.get('image'):src=d['image'];cap=d['caption']
 else:return '<div class="'+kind+'"><div class="photo-pending">Project photo to be added</div></div>'
 return '<div class="'+kind+'"><img src="'+pre+e(src)+'" alt="'+e(cap)+'" loading="lazy"></div>'
def card(id,pre=''):
 d=by[id];terms=' '.join([titles[id],d['contribution']]+d['tags'])
 return '<article class="project showcase-card" data-project data-domain="'+d['domain']+'" data-search="'+e(terms)+'"><a href="'+pre+'projects/'+id+'/">'+visual(d,pre)+'<div class="project-body"><p class="meta">'+e(labels[d['domain']])+'</p><h3>'+e(titles[id])+'</h3><p class="summary">'+e(d['problem'])+'</p><p class="project-stage">'+e(d['status'])+'</p><span class="more">Explore this project →</span></div></a></article>'
home=(D/'index.html').read_text(encoding='utf-8')
def page(title,body,pre='../'):
 prefix=home[:home.index('<main')];suffix=home[home.index('<footer class="footer"'):]
 for asset in ['assets/','index.html','projects/','about/','blog/','technical-notes/']:
  prefix=prefix.replace('href="'+asset,'href="'+pre+asset)
  suffix=suffix.replace('href="'+asset,'href="'+pre+asset).replace('src="'+asset,'src="'+pre+asset)
 prefix=re.sub(r'<title>.*?</title>','<title>'+e(title)+' | Achraf RAHIBE</title>',prefix)
 return prefix+body+suffix
start=home.index('<section class="section" id="projects">');end=home.index('<section class="section"><div class="section-title"><h2>Technical documents',start)
show='<section class="section" id="projects"><div class="section-title"><h2>Engineering projects</h2><a href="projects/">Browse all projects →</a></div><p class="section-note">Aircraft builds, complete robotic systems and marine platforms. Open each project directly for the engineering work, photographs, test material and documents.</p><div class="showcase-index"><a href="#project-aircraft">Aircraft</a><a href="#project-rotorcraft">Rotorcraft</a><a href="#project-systems">Robotics &amp; marine systems</a></div>'
for anchor,title,subset in [('project-aircraft','Fixed-wing & VTOL aircraft',ids[:5]),('project-rotorcraft','Multirotors & single-rotor helicopter',ids[5:12]),('project-systems','Ground robotics, USVs & avionics',ids[12:])]:
 show+='<section class="showcase-group" id="'+anchor+'"><h3 class="showcase-heading">'+e(title)+'</h3><div class="project-grid">'+''.join(card(id) for id in subset)+'</div></section>'
show+='</section>';home=home[:start]+show+home[end:];(D/'index.html').write_text(home,encoding='utf-8')
filters='<button data-domain-filter="" aria-pressed="true">All projects</button>'+''.join('<button data-domain-filter="'+k+'" aria-pressed="false">'+e(v)+'</button>' for k,v in labels.items())
support=[d for d in data if d['id'] not in ids]
links=''.join('<a class="support-record" href="'+d['id']+'/"><strong>'+e(d['title'])+'</strong><span>'+e(d['status'])+'</span></a>' for d in support)
body='<main id="main" class="wrap"><header class="page-head"><p class="kicker">Design · Integration · Field testing</p><h1>Engineering projects</h1><p>Explore individual aircraft and vehicle systems directly. Each project brings together the design, electronics, configuration and testing involved, with the delivered stage stated clearly.</p></header><div class="filters"><div class="filter-buttons" role="group" aria-label="Filter project domain">'+filters+'</div><input id="project-search" type="search" aria-label="Search projects" placeholder="Search aircraft, systems or tools"></div><p class="count" id="result-count" role="status" aria-live="polite"></p><section class="section"><div class="project-grid">'+''.join(card(id,'../') for id in ids)+'</div><p class="empty" id="empty" hidden>No matching projects. Clear the search or choose another category.</p></section><section class="section"><div class="section-title"><h2>Engineering studies & supporting work</h2></div><p class="section-note">Related design packages, simulation, subsystem work and diagnostic reports, with their delivery stage shown separately.</p><div class="support-grid">'+links+'</div></section></main>'
(D/'projects/index.html').write_text(page('Projects',body),encoding='utf-8')
extra=json.loads((ROOT/'content/project-stories.json').read_text(encoding='utf-8'));existing=json.loads((ROOT/'content/blog.json').read_text(encoding='utf-8'));posts=extra+[p for p in existing if p['id'] not in {x['id'] for x in extra}];entries=[]
for post in posts:
 d=by[post['case']];new=post in extra;date='28 October 2026' if new else '26 October 2026';dt='2026-10-28' if new else '2026-10-26'
 pic=visual(d,'../','blog-image') if d.get('photo_verified') or d.get('reference_images') else ''
 entries.append('<article class="blog-card journal-entry" data-story data-search="'+e(post['title']+' '+post['intro']+' '+d['title'])+'"><div class="blog-heading"><h2><a href="'+post['id']+'/">'+e(post['title'])+'</a></h2><time datetime="'+dt+'">'+date+'</time></div><p class="journal-deck">'+e(post['intro'])+'</p>'+pic+'<div class="journal-copy"><p>'+e(post['sections'][0][1])+'</p></div><div class="links"><a href="'+post['id']+'/">Read the story →</a><a href="../projects/'+d['id']+'/">View project →</a></div></article>')
 if new:
  out=D/'blog'/post['id'];out.mkdir(exist_ok=True);sections=''.join('<section><h2>'+e(h)+'</h2><p>'+e(p)+'</p></section>' for h,p in post['sections']);related=''.join('<a href="../../technical-notes/'+p+'/">Related technical document →</a>' for p in d.get('papers',[]))
  article='<main id="main" class="wrap"><header class="article-head"><p class="breadcrumb"><a href="../">Blog</a> / Project story</p><h1>'+e(post['title'])+'</h1><p class="lead">'+e(post['intro'])+'</p><p class="blog-meta">Achraf RAHIBE · '+date+' · Project retrospective</p></header>'+visual(d,'../../','case-cover')+'<div class="reading-copy">'+sections+'<section class="scope"><h2>Project record</h2><p>'+e(d['scope'])+'</p></section><div class="links"><a href="../../projects/'+d['id']+'/">Full project, photographs and test material →</a>'+related+'</div></div></main>'
  (out/'index.html').write_text(page(post['title'],article,'../../'),encoding='utf-8')
body='<main id="main" class="wrap"><header class="blog-head"><h1>Blog</h1><p>Build stories, field challenges and the engineering decisions behind each project.</p></header><div class="journal-controls"><label for="story-search">Find a project story</label><input type="search" id="story-search" placeholder="Try VTOL, helicopter, waterjet or tuning"><p id="story-count" role="status" aria-live="polite">'+str(len(posts))+' project stories</p></div>'+''.join(entries)+'<p id="story-empty" hidden>No stories match this search.</p></main>'
(D/'blog/index.html').write_text(page('Blog',body),encoding='utf-8');(D/'blog/stories.json').write_text(json.dumps(posts,ensure_ascii=False,indent=2),encoding='utf-8')
(D/'assets/project-showcase.css').write_text('''.showcase-index{display:flex;flex-wrap:wrap;gap:12px 28px;margin:24px 0 42px;font-size:13px}.showcase-group{margin:0 0 48px;scroll-margin-top:100px}.showcase-heading{font-size:19px;font-weight:500;color:var(--muted);border-top:1px solid var(--line);padding-top:24px;margin:0 0 25px}.showcase-card h3{font-size:22px}.showcase-card .cover{aspect-ratio:1.65}.project-stage{font-size:11px;color:var(--accent);margin:0 0 13px}.support-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 36px}.support-record{display:block;padding:20px 0;border-top:1px solid var(--line);text-decoration:none}.support-record strong{display:block;color:var(--ink);font-size:15px;font-weight:500}.support-record span{display:block;font-size:12px;color:var(--muted);margin-top:6px}.journal-controls{max-width:650px;margin:0 auto 45px}.journal-controls label{display:block;font-size:13px;margin-bottom:9px}.journal-controls input{width:100%;padding:12px 15px;font:inherit;color:var(--ink);background:var(--card);border:1px solid var(--line)}.journal-controls p{font-size:12px;color:var(--muted)}.journal-entry .blog-heading a{color:var(--ink)}.journal-entry .blog-image{margin-inline:0}@media(max-width:650px){.support-grid{grid-template-columns:1fr}.showcase-card h3{font-size:21px}.showcase-group{margin-bottom:32px}}''',encoding='utf-8')
(D/'assets/project-showcase.js').write_text("const storySearch=document.getElementById('story-search');storySearch?.addEventListener('input',()=>{const term=storySearch.value.trim().toLowerCase();let n=0;for(const story of document.querySelectorAll('[data-story]')){story.hidden=!story.dataset.search.toLowerCase().includes(term);if(!story.hidden)n++;}document.getElementById('story-count').textContent=n+' project stories';document.getElementById('story-empty').hidden=n!==0;});",encoding='utf-8')
paths=[D/'index.html',D/'projects/index.html',D/'blog/index.html']+[D/'blog'/p['id']/'index.html' for p in extra]
for path in paths:
 pre='' if path==D/'index.html' else ('../../' if path.parent.parent==D/'blog' else '../');t=path.read_text(encoding='utf-8');t=re.sub(r'(assets/site.js)\?[^\"]*',r'\1?v=20261028-showcase',t);t=t.replace('</head>','<link rel="stylesheet" href="'+pre+'assets/project-showcase.css?v=20261028"></head>').replace('</body>','<script src="'+pre+'assets/project-showcase.js?v=20261028" defer></script></body>');path.write_text(t,encoding='utf-8')
s=D/'assets/site.js';s.write_text(s.read_text(encoding='utf-8').replace("+' platform portfolios'","+' projects'"),encoding='utf-8')
(ROOT/'content/showcase.json').write_text(json.dumps({'main_projects':ids,'titles':titles,'story_count':len(posts)},indent=2),encoding='utf-8')
print('Showcase:',len(ids),'direct project cards on both pages;',len(posts),'stories;',len(support),'supporting records.')
